from lib import R
F = "71-desserts-more.txt"; B = "72-gluten-free-vegan-baking.txt"
DS = [
 ("Panna Cotta with Berries", "Italian", 10, 5, 6, "Dessert", "500 ml|heavy cream; 120 ml|milk; 70 g|sugar; 1 tsp|vanilla extract; 2 tsp|gelatin powder; 200 g|mixed berries", "Sprinkle the gelatin over 3 tbsp cold water and leave 5 minutes / Warm the cream, milk and sugar until steaming, take off the heat and stir in the gelatin and vanilla until dissolved / Pour into 6 glasses and chill at least 4 hours; top with berries"),
 ("Dark Chocolate Mousse", "French", 20, 5, 6, "Dessert", "200 g|dark chocolate; 4|eggs, separated; 2 tbsp|sugar; 200 ml|heavy cream; 1 pinch|salt", "Melt the chocolate and cool slightly, then stir in the yolks / Whip the cream to soft peaks and fold in / Whisk the whites with the salt and sugar to soft peaks and fold in gently / Spoon into glasses and chill 3 hours; it contains raw egg"),
 ("Bread and Butter Pudding", "British", 15, 40, 6, "Dessert", "8 slices|bread, buttered; 60 g|raisins; 3|eggs; 400 ml|milk; 150 ml|heavy cream; 60 g|sugar; 1 tsp|vanilla extract; 0.5 tsp|nutmeg", "Layer the bread, buttered side up, in a dish with the raisins / Whisk the eggs, milk, cream, sugar and vanilla, pour over and leave 20 minutes / Grate over nutmeg and bake at 170 °C (340 °F) for 35 to 40 minutes until just set"),
 ("Lemon Mousse", "International", 15, 0, 6, "Dessert", "300 ml|heavy cream; 1 can|sweetened condensed milk; 3|lemons, zested and juiced", "Whisk the condensed milk with the lemon juice and zest until it thickens / Whip the cream to soft peaks and fold in / Spoon into glasses and chill 2 hours"),
 ("Chocolate Bark with Nuts and Fruit", "International", 10, 5, 8, "Dessert, Snack", "250 g|dark chocolate; 50 g|pistachios, chopped; 40 g|dried cranberries; 1 pinch|flaky salt", "Melt the chocolate gently / Spread thinly on a parchment-lined tray / Scatter with the nuts, cranberries and salt, chill until set and break into pieces"),
 ("Peanut Butter Fudge", "American", 10, 5, 24, "Dessert, Snack", "250 g|peanut butter; 115 g|butter; 300 g|powdered sugar; 1 tsp|vanilla extract", "Melt the peanut butter and butter together / Stir in the powdered sugar and vanilla until smooth / Press into a lined 20 cm (8-inch) tin, chill 2 hours and cut into squares"),
 ("Classic Pavlova", "Australian", 20, 90, 8, "Dessert", "4|egg whites; 220 g|sugar; 1 tsp|white vinegar; 2 tsp|cornstarch; 300 ml|heavy cream; 300 g|mixed berries; 2|passion fruits", "Heat the oven to 120 °C (250 °F) / Whisk the whites to stiff peaks, then add the sugar a spoon at a time until glossy; fold in the vinegar and cornstarch / Spread into a 20 cm round on parchment and bake 1 1/4 to 1 1/2 hours; cool in the oven / Top with whipped cream and fruit just before serving"),
 ("Key Lime Bars", "American", 20, 30, 16, "Dessert", "200 g|graham cracker crumbs; 80 g|butter, melted; 2 tbsp|sugar; 1 can|sweetened condensed milk; 3|egg yolks; 4|limes, zested and juiced", "Heat the oven to 175 °C (350 °F) / Press the crumbs, butter and sugar into a lined 20 cm (8-inch) tin and bake 10 minutes / Whisk the condensed milk, yolks, lime juice and zest, pour over and bake 15 to 18 minutes until set / Cool and chill 3 hours before cutting"),
 ("Baked Apples with Oats and Cinnamon", "American", 10, 35, 4, "Dessert", "4|apples, cored; 40 g|rolled oats; 30 g|brown sugar; 30 g|butter, softened; 1 tsp|cinnamon; 30 g|raisins; 120 ml|apple juice", "Heat the oven to 180 °C (350 °F) / Mix the oats, sugar, butter, cinnamon and raisins and pack into the apples / Stand in a dish with the juice and bake 30 to 35 minutes until tender"),
 ("Strawberry Sorbet", "Italian", 10, 0, 6, "Dessert", "600 g|strawberries; 150 g|sugar; 1|lemon; 150 ml|water", "Dissolve the sugar in the water over heat and cool / Blend with the strawberries and lemon juice and strain / Churn in an ice-cream machine, or freeze in a tub and stir with a fork every 45 minutes for 3 hours"),
 ("Avocado Chocolate Mousse", "International", 10, 0, 4, "Dessert", "2|avocados, ripe; 40 g|cocoa powder; 80 ml|maple syrup; 60 ml|almond milk; 1 tsp|vanilla extract; 1 pinch|salt", "Blend everything until completely smooth / Taste and add more maple syrup if needed / Chill 1 hour; it is vegan and gluten-free"),
 ("Chocolate Chia Pudding", "International", 5, 0, 4, "Dessert, Breakfast", "60 g|chia seeds; 500 ml|almond milk; 3 tbsp|cocoa powder; 3 tbsp|maple syrup; 1 tsp|vanilla extract", "Whisk the cocoa, maple syrup and vanilla into the milk / Stir in the chia, wait 10 minutes and whisk again / Chill overnight and serve with fruit"),
 ("Meringue Kisses", "French", 15, 60, 12, "Dessert, Snack", "3|egg whites; 170 g|sugar; 0.25 tsp|cream of tartar; 1 tsp|vanilla extract", "Heat the oven to 100 °C (210 °F) / Whisk the whites and cream of tartar to soft peaks, then add the sugar gradually until stiff and glossy; add the vanilla / Pipe small kisses onto parchment and bake 1 hour, then cool in the oven"),
 ("Almond Biscotti", "Italian", 20, 45, 24, "Dessert, Snack, Baked goods", "280 g|flour; 200 g|sugar; 1 tsp|baking powder; 3|eggs; 1 tsp|almond extract; 150 g|almonds, whole; 1 pinch|salt", "Heat the oven to 175 °C (350 °F) / Mix the dry ingredients, add the eggs and extract, then the almonds, to a sticky dough / Shape two logs and bake 25 minutes; cool 10 minutes, slice diagonally and bake the slices 10 minutes per side until crisp"),
 ("Blueberry Cobbler", "Southern US", 15, 40, 6, "Dessert", "600 g|blueberries; 100 g|sugar; 1|lemon; 1 tbsp|cornstarch; 200 g|flour; 2 tsp|baking powder; 80 g|butter, cold; 180 ml|buttermilk; 1 pinch|salt", "Heat the oven to 190 °C (375 °F) / Toss the berries with half the sugar, lemon and cornstarch in a dish / Rub the butter into the flour, baking powder, salt and the rest of the sugar, stir in the buttermilk and drop spoonfuls over the fruit / Bake 35 to 40 minutes until golden and bubbling"),
 ("Peach Crisp", "American", 15, 40, 6, "Dessert", "6|peaches, sliced; 2 tbsp|sugar; 1 tbsp|cornstarch; 80 g|rolled oats; 60 g|flour; 80 g|brown sugar; 80 g|butter, cold; 0.5 tsp|cinnamon", "Heat the oven to 180 °C (350 °F) / Toss the peaches with the sugar and cornstarch in a dish / Rub the oats, flour, brown sugar, butter and cinnamon to a crumble and scatter over / Bake 35 to 40 minutes until golden"),
 ("Vanilla Custard", "British", 5, 10, 4, "Dessert", "500 ml|milk; 4|egg yolks; 60 g|sugar; 1 tbsp|cornstarch; 1 tsp|vanilla extract", "Heat the milk until steaming / Whisk the yolks, sugar and cornstarch, pour on the hot milk while whisking and return to the pan / Stir over low heat until it coats a spoon; add the vanilla"),
 ("Cannoli Dip", "Italian-American", 10, 0, 8, "Dessert, Snack", "450 g|ricotta, drained; 100 g|mascarpone; 80 g|powdered sugar; 1 tsp|vanilla extract; 1|orange, zested; 60 g|mini chocolate chips", "Beat the ricotta, mascarpone, sugar, vanilla and zest until smooth / Fold in the chocolate chips / Chill and serve with broken waffle cones or biscuits"),
 ("S'mores Bars", "American", 15, 25, 16, "Dessert, Baked goods", "200 g|graham cracker crumbs; 100 g|butter, melted; 50 g|sugar; 200 g|milk chocolate, chopped; 150 g|marshmallows", "Heat the oven to 175 °C (350 °F) / Press the crumbs, butter and sugar into a lined 20 cm (8-inch) tin and bake 10 minutes / Scatter with chocolate and marshmallows and bake 8 to 10 minutes until puffed; cool before cutting"),
 ("Crispy Rice Cereal Treats", "American", 5, 5, 16, "Dessert, Snack", "50 g|butter; 300 g|marshmallows; 150 g|puffed rice cereal; 1 tsp|vanilla extract", "Melt the butter and marshmallows over low heat, stirring / Stir in the vanilla and cereal until coated / Press into a buttered tin, cool and cut"),
 ("Gulab Jamun", "Indian", 20, 25, 6, "Dessert", "100 g|milk powder; 30 g|flour; 0.25 tsp|baking soda; 1 tbsp|ghee; 4 tbsp|milk; 300 g|sugar; 300 ml|water; 4|cardamom pods; 1 tsp|rose water; 500 ml|vegetable oil, for frying", "Simmer the sugar, water and cardamom 5 minutes and add the rose water / Mix the milk powder, flour, soda, ghee and milk to a soft dough and roll 16 smooth balls / Fry gently at about 150 °C, turning, for 6 to 8 minutes until deep brown / Soak in the warm syrup for at least 1 hour"),
 ("Kheer (Indian Rice Pudding)", "Indian", 5, 45, 6, "Dessert", "80 g|basmati rice; 1 l|milk; 80 g|sugar; 4|cardamom pods, crushed; 1 pinch|saffron; 30 g|pistachios, chopped; 30 g|almonds, sliced", "Rinse the rice and simmer in the milk with the cardamom, stirring often, for 35 to 40 minutes until creamy / Stir in the sugar and saffron and cook 5 minutes / Serve warm or chilled with the nuts"),
 ("Basque Burnt Cheesecake", "Spanish", 15, 50, 10, "Dessert, Baked goods", "900 g|cream cheese, room temperature; 250 g|sugar; 5|eggs; 400 ml|heavy cream; 30 g|flour; 1 pinch|salt", "Heat the oven to 220 °C (425 °F) and line a 23 cm (9-inch) springform with crumpled parchment / Beat the cream cheese and sugar, then the eggs one at a time, then the cream; sift in the flour and salt / Bake 45 to 55 minutes until deeply browned with a wobbly centre / Cool completely, then chill before slicing"),
 ("Apple Strudel", "Austrian", 30, 40, 8, "Dessert, Baked goods", "6 sheets|phyllo dough; 80 g|butter, melted; 4|apples, thinly sliced; 60 g|sugar; 1 tsp|cinnamon; 50 g|raisins; 40 g|breadcrumbs, toasted in butter; 1|lemon", "Heat the oven to 190 °C (375 °F) / Toss the apples with the sugar, cinnamon, raisins and lemon juice / Layer the phyllo, brushing each sheet with butter and scattering with crumbs, spread the apples along one edge and roll up / Brush with butter and bake 35 to 40 minutes"),
 ("Cherry Clafoutis", "French", 15, 40, 6, "Dessert, Baked goods", "400 g|cherries, pitted; 3|eggs; 80 g|sugar; 60 g|flour; 300 ml|milk; 1 tsp|vanilla extract; 1 tbsp|butter; 1 tbsp|powdered sugar", "Heat the oven to 190 °C (375 °F) and butter a dish / Whisk the eggs and sugar, then the flour, milk and vanilla to a smooth batter / Scatter the cherries in the dish, pour over the batter and bake 35 to 40 minutes until puffed; dust with powdered sugar"),
 ("French Madeleines", "French", 15, 12, 24, "Dessert, Snack, Baked goods", "2|eggs; 100 g|sugar; 100 g|flour; 1 tsp|baking powder; 100 g|butter, melted and cooled; 1|lemon, zested", "Whisk the eggs and sugar until pale and thick / Fold in the flour, baking powder, zest and butter and chill the batter 1 hour / Spoon into buttered madeleine tins and bake at 200 °C (400 °F) for 9 to 11 minutes until domed"),
 ("Crepes Suzette", "French", 20, 15, 4, "Dessert", "8|crepes, cooked; 60 g|butter; 60 g|sugar; 2|oranges, zested and juiced; 2 tbsp|orange liqueur, opt", "Melt the butter and sugar in a wide pan until lightly caramel / Add the orange zest and juice and simmer to a syrup / Fold the crepes into quarters, warm them in the sauce and add the liqueur if using"),
 ("Dorayaki", "Japanese", 15, 15, 6, "Dessert, Snack", "2|eggs; 70 g|sugar; 1 tbsp|honey; 130 g|flour; 0.5 tsp|baking powder; 60 ml|water; 250 g|red bean paste; 1 tsp|vegetable oil", "Whisk the eggs, sugar and honey, then the flour, baking powder and water to a thick batter; rest 15 minutes / Cook 12 small pancakes in a lightly oiled pan over low heat until golden / Sandwich pairs with the red bean paste"),
 ("Brigadeiros", "Brazilian", 10, 15, 20, "Dessert, Snack", "1 can|sweetened condensed milk; 2 tbsp|cocoa powder; 1 tbsp|butter; 60 g|chocolate sprinkles", "Cook the condensed milk, cocoa and butter over low heat, stirring constantly, for 10 to 15 minutes until it pulls away from the pan / Cool on a plate / With buttered hands roll into small balls and coat in sprinkles"),
 ("Alfajores", "Argentine", 30, 12, 15, "Dessert, Snack, Baked goods", "150 g|cornstarch; 100 g|flour; 1 tsp|baking powder; 100 g|butter, softened; 70 g|sugar; 2|egg yolks; 1 tsp|vanilla extract; 300 g|dulce de leche; 40 g|shredded coconut", "Beat the butter and sugar, add the yolks and vanilla, then the cornstarch, flour and baking powder to a soft dough; chill 30 minutes / Roll 5 mm thick, cut 30 rounds and bake at 175 °C (350 °F) for 10 to 12 minutes without browning / Sandwich with dulce de leche and roll the edges in coconut"),
 ("Portuguese Custard Tarts", "Portuguese", 30, 20, 12, "Dessert, Baked goods", "1 sheet|puff pastry; 4|egg yolks; 100 g|sugar; 2 tbsp|cornstarch; 300 ml|milk; 1 stick|cinnamon; 1|lemon, peel in strips; 1 tsp|vanilla extract", "Heat the oven to its hottest, 250 °C (480 °F) or more / Roll the pastry into a log, cut 12 slices and press each into a muffin cup / Cook the milk, sugar, cornstarch, cinnamon and lemon peel until thick, cool slightly, remove the peel and stick and whisk in the yolks and vanilla / Fill the cases and bake 15 to 20 minutes until blistered"),
 ("Chocolate Mug Cake", "American", 3, 2, 1, "Dessert", "4 tbsp|flour; 2 tbsp|cocoa powder; 3 tbsp|sugar; 0.25 tsp|baking powder; 3 tbsp|milk; 2 tbsp|vegetable oil; 1 tbsp|chocolate chips", "Mix everything in a large microwave-safe mug / Microwave on high for 70 to 90 seconds until risen but still moist / Cool 1 minute before eating"),
 ("Hummingbird Cake", "Southern US", 25, 30, 12, "Dessert, Baked goods", "350 g|flour; 300 g|sugar; 1 tsp|baking soda; 1 tsp|cinnamon; 3|eggs; 200 ml|vegetable oil; 3|bananas, mashed; 225 g|crushed pineapple, drained; 80 g|pecans, chopped; 400 g|cream cheese frosting", "Heat the oven to 175 °C (350 °F) and line two 23 cm (9-inch) tins / Whisk the dry ingredients, then stir in the eggs, oil, bananas, pineapple and pecans / Bake 25 to 30 minutes, cool and sandwich and top with the frosting"),
 ("Marble Cake", "German", 20, 50, 10, "Dessert, Baked goods", "250 g|butter, softened; 220 g|sugar; 4|eggs; 300 g|flour; 2 tsp|baking powder; 120 ml|milk; 1 tsp|vanilla extract; 3 tbsp|cocoa powder", "Heat the oven to 175 °C (350 °F) and butter a loaf or bundt tin / Beat the butter and sugar, add the eggs, then fold in the flour, baking powder, milk and vanilla / Stir the cocoa and 2 tbsp milk into a third of the batter; layer the batters and swirl with a knife / Bake 45 to 50 minutes"),
 ("Italian Olive Oil Cake", "Italian", 15, 45, 10, "Dessert, Baked goods", "3|eggs; 200 g|sugar; 180 ml|olive oil; 180 ml|milk; 2|oranges, zested; 220 g|flour; 2 tsp|baking powder; 0.5 tsp|salt", "Heat the oven to 175 °C (350 °F) and line a 23 cm (9-inch) tin / Whisk the eggs and sugar until pale, then the oil, milk and zest / Fold in the flour, baking powder and salt and bake 40 to 45 minutes"),
 ("Tahini Halva", "Middle Eastern", 10, 10, 12, "Dessert, Snack", "300 g|tahini; 250 g|sugar; 80 ml|water; 50 g|pistachios; 1 tsp|vanilla extract", "Warm the tahini gently / Boil the sugar and water to 118 °C (245 °F), the soft-ball stage / Pour the syrup into the tahini with the vanilla and pistachios and stir just until it thickens / Press into a lined tin and cool completely before cutting"),
 ("Mochi with Sweet Red Bean", "Japanese", 20, 5, 12, "Dessert, Snack", "200 g|glutinous rice flour; 60 g|sugar; 220 ml|water; 250 g|red bean paste; 50 g|cornstarch", "Mix the rice flour, sugar and water smooth in a microwave-safe bowl / Microwave covered for 1 minute, stir, then 1 minute more and 30 seconds more until translucent / Turn onto cornstarch, divide into 12, flatten and wrap each round a ball of bean paste"),
]
for t, cu, p, c, s, meals, ings, steps in DS:
    cat = "Baking" if "Baked goods" in meals else "Dessert"
    R(F, t, cat, cu, p, c, s, meals, ings, steps)

